// R12 reviewer fresh parity probe (read-only; writes nothing to repo).
const vm = require('node:vm');
const assert = require('node:assert/strict');
const fs = require('node:fs');

const bundle = fs.readFileSync('/home/jyarwood/workspace/pi-dish-r12/public/vendor/highlight.js', 'utf8');
const context = { window: {}, console: { log() {}, warn() {}, error() {} } };
vm.runInNewContext(bundle, context, { filename: 'highlight.js' });
const bundled = context.window.hljs;

// Producer truth: actual common.js CJS export in Node.
const producer = require('/home/jyarwood/workspace/pi-dish-r12/node_modules/highlight.js/lib/common.js');

// 1. API surface identical (keys, sorted).
assert.deepEqual(Object.keys(bundled).sort(), Object.keys(producer).sort(), 'API keys differ');

// 2. Same 36 languages registered, same order-independent set.
const bl = bundled.listLanguages().sort();
const pl = producer.listLanguages().sort();
assert.deepEqual(bl, pl, 'language registry differs');
assert.equal(bl.length, 36, 'expected 36 common languages');

// 3. Self aliases point at the same instance.
assert.equal(bundled.HighlightJS, bundled, 'HighlightJS alias');
assert.equal(bundled.default, bundled, 'default alias');
assert.equal(context.window.hljs.versionString, producer.versionString);

// 4. Behavior parity on samples across many languages.
const samples = {
  javascript: 'const a = 42; // hi\nconsole.log(a);',
  python: 'def f(x):\n    return f"{x}"',
  rust: 'fn main() { println!("x"); }',
  go: 'func main() { fmt.Println("hi") }',
  java: 'class A { void m() {} }',
  bash: 'echo $HOME',
  sql: 'SELECT * FROM t WHERE a = 1;',
  yaml: 'a: 1\nb: "s"',
  json: '{"k": [1, 2]}',
  xml: '<a b="c">t</a>',
  css: 'a.b { color: red; }',
  typescript: 'const x: number = 1;',
  c: '#include <stdio.h>\nint main(void){}',
  cpp: 'template<class T> struct S {};',
  csharp: 'var x = 1;',
  kotlin: 'fun main() {}',
  ruby: 'def f; 1; end',
  php: '<?php echo 1;',
  swift: 'let x = 1',
  lua: 'local x = 1',
  perl: 'my $x = 1;',
  r: 'x <- 1',
  scala: undefined,
  markdown: '# Hi\n\n*em* **strong**',
  diff: '+ added\n- removed',
  ini: '[a]\nb=1',
  makefile: 'all:\n\techo hi',
  plaintext: 'just text',
  shell: 'ls -l',
  vbnet: 'Dim x As Integer',
  wasm: '(module)',
  graphql: 'query { f }',
  less: '@a: 1;',
  scss: '$a: 1;',
  objectivec: '@interface A @end',
  java_again: undefined,
  'python-repl': '>>> print(1)',
  'php-template': '<?= 1 ?>',
};
let cases = 0;
for (const [lang, code] of Object.entries(samples)) {
  if (code === undefined) continue;
  cases++;
  const b = bundled.highlight(code, { language: lang });
  const p = producer.highlight(code, { language: lang });
  assert.equal(b.value, p.value, `output differs for ${lang}`);
  assert.equal(b.language, p.language, `language differs for ${lang}`);
  assert.equal(b.relevance, p.relevance, `relevance differs for ${lang}`);
  // highlighted HTML actually contains hljs spans for a known case.
  if (lang === 'javascript') assert.match(b.value, /hljs-keyword/, 'no keyword span');
}

// 5. Unknown language error preserved.
assert.throws(() => bundled.highlight('x', { language: 'nope-xyz' }), /Unknown language/, 'unknown-language error missing');

// 6. autoDetection + aliases.
assert.equal(bundled.autoDetection('js').name, 'JavaScript');
assert.ok(bundled.getLanguage('py'));

// 7. highlightElement-ish API present.
assert.equal(typeof bundled.highlightElement, 'function');
assert.equal(typeof bundled.newInstance, 'function');

console.log(`PARITY-OK cases=${cases} languages=${bl.length} keys=${Object.keys(bundled).length} v=${bundled.versionString}`);

