// R12 reviewer static literal-parity check (read-only; no compiler/build).
// Compares quoted-string literal multisets per embedded module vs producer file.
const fs = require('node:fs');
const path = require('node:fs');
const root = '/home/jyarwood/workspace/pi-dish-r12';
const bundle = fs.readFileSync(root + '/public/vendor/highlight.js', 'utf8');

const markerRe = /^  \/\/ (node_modules\/highlight.js\/lib\/[^\s]+)$/gm;
const marks = [];
let m;
while ((m = markerRe.exec(bundle)) !== null) marks.push({ id: m[1], index: m.index, end: markerRe.lastIndex });

const stringRe = /'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g;
function literals(src) {
  const counts = new Map();
  for (const s of src.match(stringRe) || []) counts.set(s, (counts.get(s) || 0) + 1);
  return counts;
}

let problems = 0;
for (let i = 0; i < marks.length; i++) {
  const seg = bundle.slice(marks[i].end, i + 1 < marks.length ? marks[i + 1].index : bundle.length);
  const producerPath = root + '/' + marks[i].id;
  const producer = fs.readFileSync(producerPath, 'utf8');
  const b = literals(seg), p = literals(producer);
  const bundleOnly = [...b.keys()].filter(k => !p.has(k));
  const producerOnly = [...p.keys()].filter(k => !b.has(k));
  const countMismatch = [...b.keys()].filter(k => p.has(k) && p.get(k) !== b.get(k));
  // Producer-only literals are expected from esbuild comment stripping; verify each is comment-derivable.
  const prodCommentText = (producer.match(/\/\/[^\n]*|\/\*[\s\S]*?\*\//g) || []).join('\n');
  const unexplainedProd = producerOnly.filter(k => !prodCommentText.includes(k.slice(1, -1)));
  if (bundleOnly.length || countMismatch.length || unexplainedProd.length) {
    problems++;
    console.log(`MODULE ${marks[i].id}`);
    if (bundleOnly.length) console.log('  BUNDLE-ONLY:', JSON.stringify(bundleOnly.slice(0, 10)));
    if (countMismatch.length) console.log('  COUNT-DIFF:', JSON.stringify(countMismatch.slice(0, 10)));
    if (unexplainedProd.length) console.log('  PRODUCER-ONLY(non-comment):', JSON.stringify(unexplainedProd.slice(0, 10)));
  }
}
console.log(problems === 0 ? `LITERAL-PARITY-OK modules=${marks.length}` : `ISSUES in ${problems} module(s)`);

