function litSeq(src) { return (src.match(stringRe) || []).map(s => s.slice(1, -1)); }
function counts(seq) { const c = new Map(); for (const s of seq) c.set(s, (c.get(s) || 0) + 1); return c; }

let bad = 0, checkedModuleKeys = 0, foldsExplained = 0;
for (let i = 0; i < marks.length; i++) {
  const seg = bundle.slice(marks[i].end, i + 1 < marks.length ? marks[i + 1].index : bundle.length);
  const producer = fs.readFileSync(root + '/' + marks[i].id, 'utf8');
  const bSeq = litSeq(seg), pSeq = litSeq(producer);
  const bC = counts(bSeq), pC = counts(pSeq);

  // 1. Bundle-only contents must be: module key, or concatenation of producer contents (in producer order).
  const pOrdered = [...pSeq]; // producer literal order for fold matching
