            for (const [frag, cnt] of need) { const have = [...pOrdered.slice(start, j + 1)].filter(x => x === frag).length; if (cnt !== have) { ok = false; break; } }
            if (ok) { formed = true; foldsExplained++; break; }
          }
          if (acc.length > k.length) break;
        }
      }
