    }
  }

  // 2. Producer-only surplus contents must appear inside producer comments OR be require specifiers OR be fold fragments of a bundle literal.
  const prodComments = (producer.match(/\/\/[^\n]*|\/\*[\s\S]*?\*\//g) || []).join('\n');
  const foldedBlobs = [...surplusB.keys()].join('\u0000');
  const unexplainedP = [];
  for (const [k, extra] of surplusP) {
