      if (prodComments.includes(k)) continue;              // comment text stripped by esbuild
      if (foldedBlobs.includes(k)) continue;               // fragment absorbed into a folded bundle literal
      unexplainedP.push(k);
    }
  }

  if (unexplainedB.length || unexplainedP.length) {
    bad++;
    console.log(`MODULE ${marks[i].id}`);
    if (unexplainedB.length) console.log('  UNEXPLAINED BUNDLE-ONLY:', JSON.stringify(unexplainedB.slice(0, 5)));
    if (unexplainedP.length) console.log('  UNEXPLAINED PRODUCER-ONLY:', JSON.stringify(unexplainedP.slice(0, 5)));
  }
}
console.log(bad === 0
  ? `LITERAL-PARITY-OK modules=${marks.length} moduleKeys=${checkedModuleKeys} folds=${foldsExplained}`
  : `ISSUES in ${bad} module(s)`);

