// Strip line/block comments (no string-awareness needed for BOTH sides: quotes
// inside comments drop out of producer only; bundle keeps almost no comments).
function stripComments(src) {
  return src.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:])\/\/[^\n]*/g, '$1 ');
