    const body = raw.slice(1, -1);
    return body.split(/(\$\{[^}]*\})/).map(part =>
      part.startsWith('${') ? '\u0001INTERP\u0001'.concat(part.replace(/['"]/g, ''), '\u0001') : unesc(part)
